    "/checkout": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Place a cash-on-delivery order from the cart
         * @description Prices are re-checked at today's price, stock is taken out of stock, the better of the coupon and the automatic offer is applied (never both) and the cart is emptied. Repeating a request with the same Idempotency-Key returns the same order (uses are not counted twice).
         */
        post: {
            parameters: {
                query?: never;
                header: {
                    /** @description New random value per order */
                    "Idempotency-Key": string;
                };
                path?: never;
                cookie?: never;
            };
            requestBody: {
                content: {
                    /**
                     * @example {
                     *       "address_id": 1,
                     *       "payment_method": "cod",
                     *       "coupon_code": "WELCOME10"
                     *     }
                     */
                    "application/json": {
                        address_id: number;
                        /** @enum {string} */
                        payment_method: "cod";
                        coupon_code?: string;
                        delivery_note?: string;
                        /** @description Free gift option. Default false. */
                        is_gift?: boolean;
                        /** @description Kept only when is_gift is true (trimmed; empty = null). */
                        gift_message?: string | null;
                        /** @description The offer shown in the preview. If it no longer applies, 422 on offer_id and nothing is placed. Leave it out to accept whatever wins now. */
                        offer_id?: number;
                    };
                };
            };
            responses: {
                /** @description Same key repeated — the existing order (header Idempotent-Replayed true) */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content?: never;
                };
                /** @description Order placed */
                201: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            data?: components["schemas"]["Order"];
                        };
                    };
                };
                /** @description Cart empty or has issues, bad address, coupon or key, or offer_id sent and that offer no longer applies (nothing placed) */
                422: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content?: never;
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
